def master_plan():
    t=0.0; scenes=[]
    for i,s in enumerate(MASTER_SCRIPT,1):
        start=t;t+=float(s['seconds']);scenes.append({'index':i,'start':start,'end':t,'role':s['role'],'caption':s['caption'],'narration':s['voice'],'route':s['route'],'motion':'focus'})
    return scenes,t
